import React, { useState, useEffect } from 'react';
import { useTheme } from '../context/ThemeContext';
import { useLanguage } from '../context/LanguageContext';
import { supabase } from '../utils/supabase';

const BACKEND = process.env.REACT_APP_API_URL || 'http://localhost:5000';

export default function Settings({ user, onNavigate }) {
  const { t: theme, mode, toggleTheme } = useTheme();
  const { t, language, setLanguage } = useLanguage();
  const [activeSection, setActiveSection] = useState('account');
  const [isPrivate, setIsPrivate] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(true);
  const [showFollowers, setShowFollowers] = useState(true);
  const [showWorks, setShowWorks] = useState(true);
  const [deleteText, setDeleteText] = useState('');
  const [currentPlan, setCurrentPlan] = useState('spark');
  const [currentRank, setCurrentRank] = useState('🌱 Newcomer');
  const [loadingPlan, setLoadingPlan] = useState(true);

  const sections = [
    { id: 'account', labelKey: 'account' },
    { id: 'privacy', labelKey: 'privacy' },
    { id: 'notifications', labelKey: 'notifications' },
    { id: 'billing', labelKey: 'billing' },
    { id: 'danger', labelKey: 'dangerZone' },
  ];

  useEffect(() => {
    fetchPlanAndRank();
  }, []);

  const fetchPlanAndRank = async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) return;
      const res = await fetch(`${BACKEND}/api/stripe/my-plan`, {
        headers: { Authorization: `Bearer ${session.access_token}` }
      });
      const planData = await res.json();
      if (planData.plan) setCurrentPlan(planData.plan);
      const { data: profile } = await supabase
        .from('profiles')
        .select('rank')
        .eq('user_id', session.user.id)
        .single();
      if (profile?.rank) setCurrentRank(profile.rank);
    } catch (err) {
      console.error('Settings fetch error:', err);
    } finally {
      setLoadingPlan(false);
    }
  };

  const handleUpgrade = async (plan) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const res = await fetch(`${BACKEND}/api/stripe/checkout`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.access_token}`
        },
        body: JSON.stringify({ plan })
      });
      const data = await res.json();
      if (data.url) window.location.href = data.url;
    } catch (err) {
      console.error('Upgrade error:', err);
    }
  };

  const Toggle = ({ value, onChange }) => (
    <div
      onClick={() => onChange(!value)}
      style={{
        width: '44px', height: '24px', borderRadius: '12px',
        background: value ? theme.accent : theme.bgTertiary,
        border: `1px solid ${value ? theme.accent : theme.border}`,
        position: 'relative', cursor: 'pointer', transition: 'all 0.2s'
      }}
    >
      <div style={{
        position: 'absolute', top: '2px',
        left: value ? '22px' : '2px',
        width: '18px', height: '18px', borderRadius: '50%',
        background: 'white', transition: 'left 0.2s',
        boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
      }} />
    </div>
  );

  const SettingRow = ({ label, desc, children }) => (
    <div style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      padding: '16px 0', borderBottom: `1px solid ${theme.border}`
    }}>
      <div>
        <p style={{ color: theme.textPrimary, fontSize: '14px', fontWeight: 500, margin: '0 0 2px' }}>{label}</p>
        {desc && <p style={{ color: theme.textMuted, fontSize: '12px', margin: 0 }}>{desc}</p>}
      </div>
      {children}
    </div>
  );

  const planMeta = {
    spark: { label: 'Spark', color: '#94a3b8', icon: '✏️' },
    creator: { label: 'Creator', color: '#3b82f6', icon: '🎨' },
    masterpiece: { label: 'Masterpiece', color: '#a855f7', icon: '🌌' },
  };

  return (
    <div>
      <div style={{ marginBottom: '28px' }}>
        <h1 style={{ color: theme.textPrimary, fontSize: '32px', fontWeight: 700, margin: '0 0 6px' }}>{t('settingsTitle')}</h1>
        <p style={{ color: theme.textSecondary, fontSize: '15px', margin: 0 }}>{t('settingsDesc')}</p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '200px 1fr', gap: '24px' }}>

        {/* Sidebar Nav */}
        <div style={{
          background: theme.bgCard, border: `1px solid ${theme.border}`,
          borderRadius: '12px', padding: '8px', height: 'fit-content'
        }}>
          {sections.map(section => (
            <div
              key={section.id}
              onClick={() => setActiveSection(section.id)}
              style={{
                padding: '9px 12px', borderRadius: '8px', cursor: 'pointer',
                background: activeSection === section.id ? theme.accentSubtle : 'transparent',
                color: activeSection === section.id ? theme.accent : theme.textSecondary,
                fontSize: '13px', fontWeight: activeSection === section.id ? 600 : 400,
                transition: 'all 0.15s',
                borderLeft: activeSection === section.id ? `2px solid ${theme.accent}` : '2px solid transparent'
              }}
            >
              {section.id === 'danger' ? '⚠️ ' : ''}{t(section.labelKey)}
            </div>
          ))}
        </div>

        {/* Content */}
        <div style={{
          background: theme.bgCard, border: `1px solid ${theme.border}`,
          borderRadius: '12px', padding: '24px'
        }}>

          {/* ACCOUNT */}
          {activeSection === 'account' && (
            <div>
              <h3 style={{ color: theme.textPrimary, fontSize: '16px', fontWeight: 600, margin: '0 0 20px' }}>{t('account')}</h3>
              <SettingRow label={t('emailAddress')} desc={t('primaryEmail')}>
                <span style={{ color: theme.textSecondary, fontSize: '13px' }}>{user?.email}</span>
              </SettingRow>
              <SettingRow label={t('username')} desc={t('displayName')}>
                <input
                  defaultValue={user?.email?.split('@')[0]}
                  style={{
                    padding: '6px 10px', background: theme.bgSecondary,
                    border: `1px solid ${theme.border}`, borderRadius: '6px',
                    color: theme.textPrimary, fontSize: '13px', outline: 'none', width: '160px'
                  }}
                />
              </SettingRow>
              <SettingRow label={t('theme')} desc={t('preferredTheme')}>
                <button
                  onClick={toggleTheme}
                  style={{
                    padding: '6px 14px', background: theme.bgSecondary,
                    border: `1px solid ${theme.border}`, borderRadius: '6px',
                    color: theme.textPrimary, fontSize: '13px', cursor: 'pointer',
                    display: 'flex', alignItems: 'center', gap: '6px'
                  }}
                >
                  {mode === 'dark' ? `🌙 ${t('dark')}` : `☀️ ${t('light')}`}
                </button>
              </SettingRow>

              {/* Language Switcher */}
              <SettingRow label={t('language')} desc={t('languageDesc')}>
                <select
                  value={language}
                  onChange={e => setLanguage(e.target.value)}
                  style={{
                    padding: '6px 10px', background: theme.bgSecondary,
                    border: `1px solid ${theme.border}`, borderRadius: '6px',
                    color: theme.textPrimary, fontSize: '13px', outline: 'none', cursor: 'pointer'
                  }}
                >
                  <option value="en">🇬🇧 English</option>
                  <option value="ta">🇮🇳 தமிழ்</option>
                  <option value="hi">🇮🇳 हिंदी</option>
                </select>
              </SettingRow>

              <SettingRow label={t('contributionRank')} desc={t('rankDesc')}>
                <span style={{
                  padding: '4px 12px', borderRadius: '20px',
                  background: theme.accentSubtle, color: theme.accent,
                  fontSize: '12px', fontWeight: 600
                }}>
                  {currentRank}
                </span>
              </SettingRow>
              <SettingRow label={t('currentPlan')} desc={t('subscriptionPlan')}>
                <span style={{
                  padding: '4px 12px', borderRadius: '20px',
                  background: `${planMeta[currentPlan]?.color}22`,
                  color: planMeta[currentPlan]?.color,
                  fontSize: '12px', fontWeight: 600
                }}>
                  {planMeta[currentPlan]?.icon} {planMeta[currentPlan]?.label}
                </span>
              </SettingRow>
              <SettingRow label={t('changePassword')} desc={t('updatePassword')}>
                <button style={{
                  padding: '6px 14px', background: theme.bgSecondary,
                  border: `1px solid ${theme.border}`, borderRadius: '6px',
                  color: theme.textPrimary, fontSize: '13px', cursor: 'pointer'
                }}>
                  {t('updatePassword')}
                </button>
              </SettingRow>
            </div>
          )}

          {/* PRIVACY */}
          {activeSection === 'privacy' && (
            <div>
              <h3 style={{ color: theme.textPrimary, fontSize: '16px', fontWeight: 600, margin: '0 0 20px' }}>{t('privacy')}</h3>
              <SettingRow label={t('privateProfile')} desc={t('privateProfileDesc')}>
                <Toggle value={isPrivate} onChange={setIsPrivate} />
              </SettingRow>
              <SettingRow label={t('showLeaderboard')} desc={t('showLeaderboardDesc')}>
                <Toggle value={showLeaderboard} onChange={setShowLeaderboard} />
              </SettingRow>
              <SettingRow label={t('showFollowers')} desc={t('showFollowersDesc')}>
                <Toggle value={showFollowers} onChange={setShowFollowers} />
              </SettingRow>
              <SettingRow label={t('showWorks')} desc={t('showWorksDesc')}>
                <Toggle value={showWorks} onChange={setShowWorks} />
              </SettingRow>
            </div>
          )}

          {/* NOTIFICATIONS */}
          {activeSection === 'notifications' && (
            <div>
              <h3 style={{ color: theme.textPrimary, fontSize: '16px', fontWeight: 600, margin: '0 0 20px' }}>{t('notifications')}</h3>
              <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '0 0 16px' }}>{t('siteNotifications')}</p>
              <SettingRow label={t('starAlerts')}><Toggle value={true} onChange={() => {}} /></SettingRow>
              <SettingRow label={t('likeNotifications')}><Toggle value={true} onChange={() => {}} /></SettingRow>
              <SettingRow label={t('commentNotifications')}><Toggle value={true} onChange={() => {}} /></SettingRow>
              <SettingRow label={t('dmNotifications')}><Toggle value={true} onChange={() => {}} /></SettingRow>
              <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '16px 0' }}>{t('emailNotifications')}</p>
              <SettingRow label={t('platformUpdates')}><Toggle value={false} onChange={() => {}} /></SettingRow>
              <SettingRow label={t('weeklyDigest')}><Toggle value={false} onChange={() => {}} /></SettingRow>
            </div>
          )}

          {/* BILLING */}
          {activeSection === 'billing' && (
            <div>
              <h3 style={{ color: theme.textPrimary, fontSize: '16px', fontWeight: 600, margin: '0 0 8px' }}>{t('billingPlans')}</h3>
              <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '0 0 20px' }}>
                {t('currentPlanLabel')}: <strong style={{ color: planMeta[currentPlan]?.color }}>
                  {planMeta[currentPlan]?.icon} {planMeta[currentPlan]?.label}
                </strong>
              </p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '12px' }}>
                {[
                  { id: 'spark', name: 'Spark', price: 'Free', color: '#94a3b8', icon: '✏️' },
                  { id: 'creator', name: 'Creator', price: '₹299/mo', color: '#3b82f6', icon: '🎨' },
                  { id: 'masterpiece', name: 'Masterpiece', price: '₹999/mo', color: '#a855f7', icon: '🌌' },
                ].map(plan => {
                  const isCurrent = currentPlan === plan.id;
                  return (
                    <div key={plan.id} style={{
                      background: theme.bgSecondary,
                      border: `1px solid ${isCurrent ? plan.color : theme.border}`,
                      borderRadius: '10px', padding: '16px', textAlign: 'center'
                    }}>
                      <p style={{ fontSize: '22px', margin: '0 0 4px' }}>{plan.icon}</p>
                      <p style={{ color: plan.color, fontWeight: 700, fontSize: '16px', margin: '0 0 4px' }}>{plan.name}</p>
                      <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '0 0 12px' }}>{plan.price}</p>
                      {isCurrent
                        ? <span style={{ color: theme.success, fontSize: '12px' }}>✅ {t('currentPlanLabel')}</span>
                        : plan.id !== 'spark' && (
                          <button
                            onClick={() => handleUpgrade(plan.id)}
                            style={{
                              padding: '6px 16px', background: plan.color,
                              color: 'white', border: 'none', borderRadius: '6px',
                              cursor: 'pointer', fontSize: '12px', fontWeight: 600
                            }}
                          >
                            {t('upgrade')}
                          </button>
                        )
                      }
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* DANGER ZONE */}
          {activeSection === 'danger' && (
            <div>
              <h3 style={{ color: theme.danger, fontSize: '16px', fontWeight: 600, margin: '0 0 20px' }}>⚠️ {t('dangerZone')}</h3>
              <div style={{
                background: theme.dangerSubtle, border: `1px solid ${theme.danger}44`,
                borderRadius: '10px', padding: '20px'
              }}>
                <p style={{ color: theme.textPrimary, fontWeight: 600, fontSize: '14px', margin: '0 0 4px' }}>{t('deleteAccount')}</p>
                <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '0 0 16px' }}>{t('deleteDesc')}</p>
                <p style={{ color: theme.textSecondary, fontSize: '13px', margin: '0 0 8px' }}>{t('typeYes')}</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <input
                    value={deleteText}
                    onChange={e => setDeleteText(e.target.value)}
                    placeholder={t('typeYesPlaceholder')}
                    style={{
                      padding: '8px 12px', background: theme.bgSecondary,
                      border: `1px solid ${theme.border}`, borderRadius: '6px',
                      color: theme.textPrimary, fontSize: '13px', outline: 'none'
                    }}
                  />
                  <button
                    disabled={deleteText !== 'Yes'}
                    style={{
                      padding: '8px 16px',
                      background: deleteText === 'Yes' ? theme.danger : theme.bgTertiary,
                      color: deleteText === 'Yes' ? 'white' : theme.textMuted,
                      border: 'none', borderRadius: '6px',
                      fontSize: '13px', cursor: deleteText === 'Yes' ? 'pointer' : 'not-allowed'
                    }}
                  >
                    {t('deleteAccount')}
                  </button>
                </div>
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}
